1	package consensus
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// 本文件钉住“非空竞争候选登记”的原子落盘回归保障，重点是登记保存失败时
12	// 不能提前锁住原本仍可加费替换的排队交易。
13	//
14	// 场景：第 1 轮本地提议已产生且尚未确认（四验证者确认门槛为 3 票）。本地提议
15	// 按费用打包 a1、b1 两笔（单块上限 2）；另一个已登记的竞争候选只引用 a1，
16	// 并持有两张未达门槛的票，本地候选 0 票，两名验证者未投票。池中还有一笔
17	// 没有被任何候选引用的排队交易 c1。准备登记的新竞争候选为非空列表 [c1, a1]：
18	// 既包含此前只在池中排队的 c1，也包含已被现有候选引用的 a1；列表不超过单块
19	// 上限、各账户序号自 1 起连续、交易均未到期，按现有规则本应登记成功。
20	//
21	// 登记成功的公开效果是：新候选入册，其首次引用的排队交易 c1 改为等待投票，
22	// 此后同发送者同序号的加费替换会以 tx-in-proposal 被拒。因此当这次登记因
23	// 节点状态保存失败而结束时，必须整体不生效：调用收到保存错误而非登记结果；
24	// 按轮次查询仍只有原来的两个候选，本地提议的区块标识与交易顺序、各候选的
25	// 投票者与未投票名单都保持登记前结果，轮次与确认高度不前进；c1 仍显示排队、
26	// 账户仍说明等待打包，同发送者同序号、费用严格更高的新交易仍可替换它；
27	// a1、b1 等此前已被候选引用的交易继续等待投票，加费替换仍以现有的锁定原因
28	// 拒绝，不能因为新候选登记失败而被解除保护；两类交易的完整内容都不被改写，
29	// 账户已确认序号不推进。磁盘状态文件逐字节不变、不残留临时文件，重新打开
30	// 状态目录看到与失败后原节点相同的候选、投票与交易状态。
31	//
32	// 保存恢复正常后分两条路径钉住现有公开行为：
33	//   - 已对 c1 做过加费替换时，旧交易按原规则显示 replaced 并指向新交易，
34	//     原候选列表因引用已退出池的交易不能原样登记；
35	//   - 尚未替换列表中的交易时，重新提交原来的合法候选列表应成功登记并被
36	//     识别为新候选（0 票），届时 c1 才改为等待投票，原有票数仍归属于原来
37	//     的候选，本地提议保持冻结、不直接确认区块。
38	//
39	// 本组测试不新增公开入口，也不改变现有登记、投票与交易替换规则。
40	
41	// registerScene 收拢“竞争候选登记保存失败”场景的关键句柄。
42	type registerScene struct {
43		local  ProposalView
44		alt1ID string
45		// a1 被本地提议与既有竞争候选 alt1 共享引用：等待投票、禁止替换。
46		a1 *Transaction
47		// b1 仅被本地提议引用：等待投票、禁止替换。
48		b1 *Transaction
49		// c1 没有被任何候选引用，仅在池中排队：等待打包、可加费替换；
50		// 它是失败的新候选首次引用的排队交易。
51		c1 *Transaction
52		// failedList 是保存失败的那次登记本应登记的非空交易列表。
53		failedList []string
54	}
55	
56	// buildRegisterScene 在一个单块上限为 2 的新节点上构造登记前的未决场景：
57	// 本地提议 [a1, b1]（费用 10、5），竞争候选 alt1=[a1] 持两票，c1 仅排队。
58	func buildRegisterScene(t *testing.T, n *Node, keys []testKey) registerScene {
59		t.Helper()
60		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
61		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
62		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 1, 100)
63		for _, tx := range []*Transaction{a1, b1, c1} {
64			if _, err := n.Submit(tx); err != nil {
65				t.Fatalf("setup submit %q: %v", tx.Content, err)
66			}
67		}
68		// 单块上限 2：本地提议按费用取 a1(10)、b1(5)；c1(1) 留在池中排队。
69		local, err := n.Propose()
70		if err != nil {
71			t.Fatal(err)
72		}
73		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{a1.ID(), b1.ID()}) {
74			t.Fatalf("setup: local proposal = %v, want [a1 b1]", local.TxIDs)
75		}
76	
77		// 既有竞争候选只引用共享交易 a1，与本地提议标识不同。
78		alt1, err := n.RegisterCandidate(1, []string{a1.ID()})
79		if err != nil {
80			t.Fatal(err)
81		}
82		if alt1.Existing || alt1.BlockID == local.BlockID {
83			t.Fatalf("setup: existing competitor must be a fresh candidate: %+v local=%s", alt1, local.BlockID)
84		}
85	
86		// 验证者1、2 投给 alt1，各一票：两票未达四验证者的 3 票门槛；
87		// 验证者0、3 未投票，本地候选 0 票。
88		for _, i := range []int{1, 2} {
89			res, err := n.Vote(keys[i].pub, 1, alt1.BlockID)
90			if err != nil || !res.Counted || res.Confirmed {
91				t.Fatalf("setup vote for alt1 by validator %d: %+v %v", i, res, err)
92			}
93		}
94	
95		failedList := []string{c1.ID(), a1.ID()} // 顺序与本地提议不同，区块标识必然不同
96		return registerScene{
97			local:      local,
98			alt1ID:     alt1.BlockID,
99			a1:         a1,
100			b1:         b1,
101			c1:         c1,
102			failedList: failedList,
103		}
104	}
105	
106	// sceneCandidates 断言登记前/失败后始终不变的那部分轮次状态：
107	// 轮次 1、确认高度 0 且无确认块；按轮次查询恰有两个 pending 候选——
108	// 本地提议标识与交易顺序不变、0 票；alt1 保留两张原票；未投票名单为
109	// 验证者0、3。同时断言 a1、b1 继续等待投票且内容完整。
110	func sceneCandidates(t *testing.T, n *Node, sc registerScene, keys []testKey) {
111		t.Helper()
112		if n.CurrentRound() != 1 {
113			t.Fatalf("current round = %d, want 1 (failed register must not advance the round)", n.CurrentRound())
114		}
115		if n.Height() != 0 {
116			t.Fatalf("confirmed height = %d, want 0", n.Height())
117		}
118		if _, ok := n.LatestBlock(); ok {
119			t.Fatal("no confirmed block may exist after the failed register")
120		}
121		if _, err := n.BlockAt(1); reason(err) != ReasonUnknownBlock {
122			t.Fatalf("block at height 1: %v, want %s", err, ReasonUnknownBlock)
123		}
124	
125		// 本地提议始终返回同一份冻结结果。
126		p, ok := n.Proposal()
127		if !ok {
128			t.Fatal("local proposal must stay available after the failed register")
129		}
130		if p.Round != 1 || p.BlockID != sc.local.BlockID ||
131			fmt.Sprint(p.TxIDs) != fmt.Sprint(sc.local.TxIDs) {
132			t.Fatalf("local proposal changed: %+v, want id=%s order=%v", p, sc.local.BlockID, sc.local.TxIDs)
133		}
134	
135		rc, err := n.Candidates(1)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords {
140			t.Fatalf("round 1 must stay pending with records: %+v", rc)
141		}
142		if len(rc.Candidates) != 2 {
143			t.Fatalf("candidate count = %d, want 2 (the failed candidate must not be registered)", len(rc.Candidates))
144		}
145		wantUnvoted := [][]byte{keys[0].pub, keys[3].pub}
146		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys(wantUnvoted)) {
147			t.Fatalf("unvoted validators = %x, want %x", rc.Unvoted, wantUnvoted)
148		}
149	
150		var gotLocal, gotAlt *CandidateView
151		for i := range rc.Candidates {
152			switch rc.Candidates[i].BlockID {
153			case sc.local.BlockID:
154				gotLocal = &rc.Candidates[i]
155			case sc.alt1ID:
156				gotAlt = &rc.Candidates[i]
157			}
158		}
159		if gotLocal == nil || gotAlt == nil {
160			t.Fatalf("only the original candidates must remain: %+v", rc.Candidates)
161		}
162		if !gotLocal.Local || gotLocal.Result != CandidatePending ||
163			fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint([]string{sc.a1.ID(), sc.b1.ID()}) ||
164			len(gotLocal.Voters) != 0 {
165			t.Fatalf("local candidate must stay pending with its order and no votes: %+v", gotLocal)
166		}
167		if gotAlt.Local || gotAlt.Result != CandidatePending ||
168			fmt.Sprint(gotAlt.TxIDs) != fmt.Sprint([]string{sc.a1.ID()}) {
169			t.Fatalf("existing competitor must stay pending with its own tx order: %+v", gotAlt)
170		}
171		wantAltVoters := [][]byte{keys[1].pub, keys[2].pub}
172		if fmt.Sprint(hexKeys(gotAlt.Voters)) != fmt.Sprint(hexKeys(wantAltVoters)) {
173			t.Fatalf("existing competitor votes = %x, want %x", gotAlt.Voters, wantAltVoters)
174		}
175	
176		// 失败候选的区块标识绝不能出现在候选集合中。
177		failedBlockID := BlockID(1, 1, "", sc.failedList)
178		for _, c := range rc.Candidates {
179			if c.BlockID == failedBlockID {
180				t.Fatalf("failed candidate %s must not survive in the round record", failedBlockID)
181			}
182		}
183	
184		// 此前已被候选引用的交易继续等待投票，完整内容不被改写，不带确认/替换关联。
185		for _, tx := range []*Transaction{sc.a1, sc.b1} {
186			info := n.mustTx(t, tx.ID())
187			if info.Status != StatusProposed {
188				t.Fatalf("tx %q status = %s, want proposed (still referenced by an existing candidate)", tx.Content, info.Status)
189			}
190			assertTxMatches(t, info.Tx, tx)
191			if info.BlockHeight != 0 || info.BlockID != "" || info.ReplacedBy != "" {
192				t.Fatalf("tx %q must not carry block/replace links: %+v", tx.Content, info)
193			}
194		}
195		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{sc.a1.ID(): "waiting-vote"})
196		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{sc.b1.ID(): "waiting-vote"})
197	}
198	
199	// assertRegisterRolledBack 在 sceneCandidates 之上补充失败候选首次引用的
200	// 排队交易 c1 的操作前状态：仍排队、内容完整、账户说明等待打包；失败登记
201	// 不推进任何账户的已确认序号，也不制造序号缺口。
202	func assertRegisterRolledBack(t *testing.T, n *Node, sc registerScene, keys []testKey) {
203		t.Helper()
204		sceneCandidates(t, n, sc, keys)
205	
206		info := n.mustTx(t, sc.c1.ID())
207		if info.Status != StatusQueued {
208			t.Fatalf("newly referenced tx c1 status = %s, want queued after the failed register", info.Status)
209		}
210		assertTxMatches(t, info.Tx, sc.c1)
211		if info.BlockHeight != 0 || info.BlockID != "" || info.ReplacedBy != "" {
212			t.Fatalf("c1 must not carry block/replace links: %+v", info)
213		}
214		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{sc.c1.ID(): "waiting-pack"})
215		if a := n.Account(keys[2].pub); a.Gap != 0 {
216			t.Fatalf("account 2 gap = %d, want 0", a.Gap)
217		}
218	}
219	
220	// assertReplacementStillLocked 尝试以更高费用替换此前已被候选引用的交易，
221	// 必须继续以 tx-in-proposal 拒绝，且交易与账户状态保持不变。
222	func assertReplacementStillLocked(t *testing.T, n *Node, keys []testKey, idx int, old *Transaction) {
223		t.Helper()
224		hi := NewTransaction(keys[idx].priv, old.Sequence, []byte(string(old.Content)+"-hi"), old.Fee+900, 100)
225		if _, err := n.Submit(hi); reason(err) != ReasonProposalLocked {
226			t.Fatalf("replacing referenced tx %q must still be rejected with %s after the failed register, got %v",
227				old.Content, ReasonProposalLocked, err)
228		}
229		info := n.mustTx(t, old.ID())
230		if info.Status != StatusProposed {
231			t.Fatalf("referenced tx %q status = %s after rejected replacement, want proposed", old.Content, info.Status)
232		}
233		assertTxMatches(t, info.Tx, old)
234		if info.ReplacedBy != "" {
235			t.Fatalf("referenced tx %q must not gain a replacement link: %+v", old.Content, info)
236		}
237		if a := n.Account(keys[idx].pub); a.ConfirmedSequence != 0 {
238			t.Fatalf("account %d confirmed sequence = %d, want 0", idx, a.ConfirmedSequence)
239		}
240	}
241	
242	// TestRegisterCandidateSaveFailureAtomic 覆盖非空竞争候选登记保存失败的完整
243	// 回归序列：失败整体回滚（保存错误、结果为 nil，候选/投票/未投票名单/本地
244	// 提议/两类交易状态/账户序号全部照旧）-> 内存/磁盘/重开三处一致 -> 恢复后
245	// 首次引用的排队交易可按正常规则加费替换，而已被候选引用的交易仍被锁定。
246	func TestRegisterCandidateSaveFailureAtomic(t *testing.T) {
247		keys := genKeys(t, 4)
248		n, dir := newTestNode(t, keys, 2)
249		sc := buildRegisterScene(t, n, keys)
250	
251		// 登记前基线：与失败后应当完全一致。
252		assertRegisterRolledBack(t, n, sc, keys)
253	
254		// 快照登记前的磁盘文件：失败的保存不得改写它，也不得残留临时文件。
255		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
256		if err != nil {
257			t.Fatal(err)
258		}
259	
260		// 合法的非空候选在此刻保存节点状态失败：必须返回保存错误，
261		// 且不能同时给出成功的登记结果。
262		n.injectSaveErr = errors.New("disk full (simulated)")
263		res, err := n.RegisterCandidate(1, sc.failedList)
264		n.injectSaveErr = nil
265		if err == nil {
266			t.Fatal("register candidate must return the save error when saving node state fails")
267		}
268		if reason(err) != "" {
269			t.Fatalf("save failure must surface as an infrastructure error, not a rejection %q: %v", reason(err), err)
270		}
271		if res != nil {
272			t.Fatalf("register result must be nil on save failure, got %+v", res)
273		}
274	
275		// 内存：候选、票、未投票名单、本地提议不变；c1 没有被提前锁住，
276		// a1、b1 没有被解除保护，账户序号不推进。
277		assertRegisterRolledBack(t, n, sc, keys)
278	
279		// 磁盘：状态文件逐字节不变，目录中仅有 state.json。
280		assertStateFileUnchanged(t, dir, before)
281	
282		// 在执行任何后续替换之前重开节点：必须得到与失败后原节点相同的
283		// 候选、投票与交易状态，不能恢复出未成功登记的候选或它造成的锁定。
284		reopened, err := Open(dir)
285		if err != nil {
286			t.Fatal(err)
287		}
288		assertRegisterRolledBack(t, reopened, sc, keys)
289	
290		// 保存恢复正常后，失败候选首次引用的排队交易 c1 仍可按原规则加费替换：
291		// 同发送者同序号、费用严格更高，替换成功并关联旧标识。
292		c1hi := NewTransaction(keys[2].priv, 1, []byte("c1-hi"), 9, 100)
293		if c1hi.ID() == sc.c1.ID() || c1hi.Fee <= sc.c1.Fee {
294			t.Fatal("setup: replacement must differ from c1 with a strictly higher fee")
295		}
296		rep, err := reopened.Submit(c1hi)
297		if err != nil {
298			t.Fatalf("queued tx c1 must stay replaceable after the failed register: %v", err)
299		}
300		if rep.TxID != c1hi.ID() || rep.ReplacedID != sc.c1.ID() || rep.EvictedID != "" {
301			t.Fatalf("replacement result = %+v, want {TxID:%s ReplacedID:%s EvictedID:\"\"}",
302				rep, c1hi.ID(), sc.c1.ID())
303		}
304		old := reopened.mustTx(t, sc.c1.ID())
305		if old.Status != StatusReplaced || old.ReplacedBy != c1hi.ID() {
306			t.Fatalf("c1 after replacement = {status:%s replacedBy:%s}, want replaced by %s",
307				old.Status, old.ReplacedBy, c1hi.ID())
308		}
309		assertTxMatches(t, old.Tx, sc.c1) // 被替换的旧交易保留完整内容
310		next := reopened.mustTx(t, c1hi.ID())
311		if next.Status != StatusQueued {
312			t.Fatalf("replacement tx status = %s, want queued", next.Status)
313		}
314		assertTxMatches(t, next.Tx, c1hi)
315		assertAccountQueue(t, reopened, keys[2].pub, 0, map[string]string{c1hi.ID(): "waiting-pack"})
316	
317		// 候选与投票、轮次与确认高度不被这笔替换改变；a1、b1 仍是等待投票。
318		sceneCandidates(t, reopened, sc, keys)
319	
320		// 原先已被其他候选引用的交易继续受到保护：加费替换仍以现有的锁定
321		// 原因拒绝，不能因为新候选登记失败而被解锁。
322		assertReplacementStillLocked(t, reopened, keys, 0, sc.a1)
323		assertReplacementStillLocked(t, reopened, keys, 1, sc.b1)
324	
325		// 替换与拒绝均已正常落盘：再次重开看到同样的结果——c1 已被替换、
326		// c1hi 排队等待打包，a1、b1 仍等待投票，候选与票数不变。
327		durable, err := Open(dir)
328		if err != nil {
329			t.Fatal(err)
330		}
331		sceneCandidates(t, durable, sc, keys)
332		dOld := durable.mustTx(t, sc.c1.ID())
333		if dOld.Status != StatusReplaced || dOld.ReplacedBy != c1hi.ID() {
334			t.Fatalf("durable c1 = {status:%s replacedBy:%s}, want replaced by %s",
335				dOld.Status, dOld.ReplacedBy, c1hi.ID())
336		}
337		assertTxMatches(t, dOld.Tx, sc.c1)
338		dNew := durable.mustTx(t, c1hi.ID())
339		if dNew.Status != StatusQueued {
340			t.Fatalf("durable replacement tx status = %s, want queued", dNew.Status)
341		}
342		assertAccountQueue(t, durable, keys[2].pub, 0, map[string]string{c1hi.ID(): "waiting-pack"})
343	
344		// c1 既已退出池，原来的候选列表不能原样登记：按现有规则以
345		// tx-not-in-pool 拒绝，节点状态不变（仍只有两个候选）。
346		if _, err := durable.RegisterCandidate(1, sc.failedList); reason(err) != ReasonTxNotInPool {
347			t.Fatalf("register list containing replaced c1 must fail with %s, got %v", ReasonTxNotInPool, err)
348		}
349		sceneCandidates(t, durable, sc, keys)
350	}
351	
352	// assertReRegistered 断言保存恢复后重新提交原合法候选列表成功后的状态：
353	// 新候选入册（0 票、pending、给定交易顺序），c1 才改为等待投票；原有候选
354	// 与票数、未投票名单不变，本地提议冻结，轮次与确认高度不前进、不确认区块。
355	func assertReRegistered(t *testing.T, n *Node, sc registerScene, newID string, keys []testKey) {
356		t.Helper()
357		if n.CurrentRound() != 1 || n.Height() != 0 {
358			t.Fatalf("round=%d height=%d, want 1/0 (registering a competitor must not confirm)",
359				n.CurrentRound(), n.Height())
360		}
361		if _, ok := n.LatestBlock(); ok {
362			t.Fatal("registering a competitor must not create a confirmed block")
363		}
364		p, ok := n.Proposal()
365		if !ok || p.BlockID != sc.local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(sc.local.TxIDs) {
366			t.Fatalf("local proposal must stay frozen: %+v ok=%v, want %+v", p, ok, sc.local)
367		}
368	
369		rc, err := n.Candidates(1)
370		if err != nil {
371			t.Fatal(err)
372		}
373		if rc.Ended || !rc.HasRecords || len(rc.Candidates) != 3 {
374			t.Fatalf("round 1 must have exactly three pending candidates: %+v", rc)
375		}
376		wantUnvoted := [][]byte{keys[0].pub, keys[3].pub}
377		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys(wantUnvoted)) {
378			t.Fatalf("unvoted validators = %x, want %x", rc.Unvoted, wantUnvoted)
379		}
380	
381		var gotLocal, gotAlt, gotNew *CandidateView
382		for i := range rc.Candidates {
383			switch rc.Candidates[i].BlockID {
384			case sc.local.BlockID:
385				gotLocal = &rc.Candidates[i]
386			case sc.alt1ID:
387				gotAlt = &rc.Candidates[i]
388			case newID:
389				gotNew = &rc.Candidates[i]
390			}
391		}
392		if gotLocal == nil || gotAlt == nil || gotNew == nil {
393			t.Fatalf("all three candidates must be present: %+v", rc.Candidates)
394		}
395		// 新候选被识别为一个独立的新候选，与本地提议、alt1 标识都不同，0 票，
396		// 且不被标记为本地提议。
397		if gotNew.Local || gotNew.Result != CandidatePending || len(gotNew.Voters) != 0 ||
398			fmt.Sprint(gotNew.TxIDs) != fmt.Sprint(sc.failedList) {
399			t.Fatalf("new candidate must be a non-local pending candidate with no votes and the original list: %+v", gotNew)
400		}
401		// 原有票数仍归属于原来的候选，没有转给新候选。
402		if !gotLocal.Local || len(gotLocal.Voters) != 0 {
403			t.Fatalf("local candidate votes changed after re-register: %+v", gotLocal)
404		}
405		wantAltVoters := [][]byte{keys[1].pub, keys[2].pub}
406		if fmt.Sprint(hexKeys(gotAlt.Voters)) != fmt.Sprint(hexKeys(wantAltVoters)) {
407			t.Fatalf("existing competitor votes = %x, want %x", gotAlt.Voters, wantAltVoters)
408		}
409	
410		// 届时新引用的排队交易 c1 才改为等待投票并进入账户的等待投票说明。
411		c1 := n.mustTx(t, sc.c1.ID())
412		if c1.Status != StatusProposed {
413			t.Fatalf("c1 status = %s, want proposed only after the successful register", c1.Status)
414		}
415		assertTxMatches(t, c1.Tx, sc.c1)
416		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{sc.c1.ID(): "waiting-vote"})
417		// 已确认序号仍不推进。
418		for i := 0; i < 3; i++ {
419			if a := n.Account(keys[i].pub); a.ConfirmedSequence != 0 {
420				t.Fatalf("account %d confirmed sequence = %d, want 0", i, a.ConfirmedSequence)
421			}
422		}
423	
424		// c1 现已被未决候选引用：加费替换按现有锁定原因拒绝。
425		c1hi := NewTransaction(keys[2].priv, 1, []byte("c1-hi-late"), 9, 100)
426		if _, err := n.Submit(c1hi); reason(err) != ReasonProposalLocked {
427			t.Fatalf("c1 must be locked after the successful register, got %v (want %s)", err, ReasonProposalLocked)
428		}
429		if info := n.mustTx(t, sc.c1.ID()); info.Status != StatusProposed || info.ReplacedBy != "" {
430			t.Fatalf("c1 must stay proposed with no replacement link after rejected replace: %+v", info)
431		}
432	}
433	
434	// TestRegisterCandidateSaveFailureRetrySucceeds 钉住恢复路径：保存失败并回滚、
435	// 重新打开节点后，在尚未替换列表中交易的情况下重新提交原来的合法候选列表，
436	// 必须成功登记并被识别为新候选（而非重复登记的既有候选），新引用的排队交易
437	// 才改为等待投票，原有投票归属不变，本地提议保持冻结、不直接确认区块。
438	func TestRegisterCandidateSaveFailureRetrySucceeds(t *testing.T) {
439		keys := genKeys(t, 4)
440		n, dir := newTestNode(t, keys, 2)
441		sc := buildRegisterScene(t, n, keys)
442	
443		wantNewID := BlockID(1, 1, "", sc.failedList)
444		if wantNewID == sc.local.BlockID || wantNewID == sc.alt1ID {
445			t.Fatal("setup: retried candidate must differ from both existing candidates")
446		}
447	
448		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
449		if err != nil {
450			t.Fatal(err)
451		}
452	
453		// 合法登记保存失败：整体回滚，内存/磁盘/重开三处一致。
454		n.injectSaveErr = errors.New("disk full (simulated)")
455		res, err := n.RegisterCandidate(1, sc.failedList)
456		n.injectSaveErr = nil
457		if err == nil {
458			t.Fatal("register candidate must return the save error when saving node state fails")
459		}
460		if reason(err) != "" {
461			t.Fatalf("save failure must surface as an infrastructure error, not a rejection %q: %v", reason(err), err)
462		}
463		if res != nil {
464			t.Fatalf("register result must be nil on save failure, got %+v", res)
465		}
466		assertRegisterRolledBack(t, n, sc, keys)
467		assertStateFileUnchanged(t, dir, before)
468	
469		reopened, err := Open(dir)
470		if err != nil {
471			t.Fatal(err)
472		}
473		assertRegisterRolledBack(t, reopened, sc, keys)
474	
475		// 保存恢复正常，且尚未替换列表中的任何交易：重新提交原列表必须成功，
476		// 并被识别为一个新候选（Existing=false），而非重复登记。
477		res, err = reopened.RegisterCandidate(1, append([]string{}, sc.failedList...))
478		if err != nil {
479			t.Fatalf("retry of the original valid list must succeed after recovery: %v", err)
480		}
481		if res.Existing {
482			t.Fatal("the retried candidate must be registered as a new candidate, not an existing one")
483		}
484		if res.BlockID != wantNewID {
485			t.Fatalf("retried block id = %s, want %s", res.BlockID, wantNewID)
486		}
487		assertReRegistered(t, reopened, sc, wantNewID, keys)
488	
489		// 成功登记随再次落盘持久化：再开一次看到完全一致的三候选、票数与锁定状态。
490		durable, err := Open(dir)
491		if err != nil {
492			t.Fatal(err)
493		}
494		assertReRegistered(t, durable, sc, wantNewID, keys)
495	}
496

