568		if p, ok := n2.Proposal(); !ok || p.BlockID != local.BlockID {
569			t.Fatalf("local proposal not restored: %+v", p)
570		}
571		// 每人的选择恢复：重复不计数、改投拒绝。
572		if res, _ := n2.Vote(keys[1].pub, 1, altID); res.Counted {
573			t.Fatal("restored vote should dedup")
574		}
