15	
16	// Config 是节点初始化时固定的配置。
17	type Config struct {
18		// Seed 决定每轮提议者的种子，任意非空字节。
19		Seed []byte
20		// Validators 固定、非空、无重复的验证者公钥名单（Ed25519 32 字节公钥）。
21		Validators [][]byte
22		// MaxTxsPerBlock 单块交易上限，必须为正整数。
23		MaxTxsPerBlock uint64
24		// PoolCapacity 交易池容量上限：非负整数，0（或省略）表示不限制。
25		// 与单块交易上限相互独立；只统计排队与等待投票的交易。
26		PoolCapacity uint64
27	}
28	
29	// entryStatus 与对外的 TxStatus 取值一致，额外区分内部存储。
30	type entryStatus string
31	
32	const (
33		stQueued    entryStatus = "queued"
34		stProposed  entryStatus = "proposed"
35		stConfirmed entryStatus = "confirmed"
36		stReplaced  entryStatus = "replaced"
37		stExpired   entryStatus = "expired"
38		stDropped   entryStatus = "dropped"
39	)
40	
41	type poolEntry struct {
42		Tx         *Transaction `json:"tx"`
43		Status     entryStatus  `json:"status"`
44		ReplacedBy string       `json:"replaced_by,omitempty"`
45		// DropReason/DropRound 仅在 Status 为 dropped 时有意义：被挤出的原因与发生轮次。
46		DropReason string `json:"drop_reason,omitempty"`
47		DropRound  uint64 `json:"drop_round,omitempty"`
48	}
49	
50	type confirmedRef struct {
51		Height uint64 `json:"height"`
52		Block  string `json:"block_id"`
53	}
54	
55	type proposalState struct {
56		Round   uint64   `json:"round"`
57		TxIDs   []string `json:"tx_ids"`
58		BlockID string   `json:"block_id"`
59		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
60	}
61	
62	// candidateState 是一轮中的一个候选块。同一轮多个候选共享相同的轮次、
63	// 下一高度与前块标识，仅交易顺序可以不同。
64	type candidateState struct {
65		TxIDs   []string `json:"tx_ids"`
66		BlockID string   `json:"block_id"`
67		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
68		// Local 标记该候选是否为本节点 Propose 产生的本地提议。
69		Local bool `json:"local"`
70		// Decided 表示该候选已决出：胜出确认或在轮次结束时落选。
71		Decided bool `json:"decided"`
72		// Winner 仅在 Decided 时有意义：true 为胜出，false 为落选。
73		Winner bool `json:"winner,omitempty"`
74	}
75	
76	// roundState 记录一个轮次的全部候选与结果。轮次决出后仍保留用于历史查询。
77	type roundState struct {
78		Round        uint64                     `json:"round"`
79		Height       uint64                     `json:"height"`     // 该轮候选使用的下一高度
80		PreviousID   string                     `json:"prev_id"`    // 该轮候选接在其后的最新确认块
81		Candidates   map[string]*candidateState `json:"candidates"` // 区块标识 -> 候选
82		LocalBlockID string                     `json:"local_block_id"`
83		// Ended 本轮已决出：候选确认或被 EndRound 主动结束。
84		Ended bool `json:"ended"`
85		// EndedByConfirm 决出方式：true 为投票确认，false 为主动结束（全部落选）。
86		EndedByConfirm bool `json:"ended_by_confirm,omitempty"`
87		// DetailMissing 表示该轮候选详情由旧版本状态迁移而来、并未保存，
88		// 查询时明确显示无记录；确认块本身不受影响。
89		DetailMissing bool `json:"detail_missing,omitempty"`
90	}
